element.reference_qual:
var ids = [];
var grm = new GlideRecord('sys_user_grmember');
grm.addQuery('group.name', 'Training Instructors');
grm.query();
while (grm.next()) ids.push(grm.user.toString());
answer = 'sys_idIN' + ids.join(',');

